INSERT INTO `master_produk` VALUES (48, 2, 9, NULL, NULL, NULL, 'Uang Emas Kopi Special', 'uang-emas-kopi-special-ues1000', 'UES1000', '<br><br>', 'Uang Emas Kopi Special<br><br>Kami mengolah Uang Emas Kopi Special dari biji kopi pilihan. Melalui kontrol kualitas yang ketat dan proses pengemasan yg higienis menghasilkan kopi dengan kenikmatan tiada tara.\r\n<br><br>\r\nSaran Penyajian:<br>Masukkan satu sachet kopi ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap untuk dinikmati.', 'Bag', '1 Bag x 1000g', 75200.00, 'images/uploads/1774410299_p_uang-emas-kopi-special-ues1000.webp', '[\"UANGEMAS/UE_1000_2.webp\", \"UANGEMAS/UE_1000_3.webp\"]', 0, '2025-01-13 11:25:51', 'https://indracostore.com/product/Uang-Emas-Kopi-Special-1-Bag-x-1000g', 'Uang-Emas-Kopi-Special-1-Bag-x-1000g', 'https://shopee.co.id/product/283021328/9531003424/', 'https://www.blibli.com/p/uang-emas-kopi-special-1kg/ps--INT-60044-00110', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:05:41');

