INSERT INTO `master_produk` VALUES (103, 8, 4, NULL, NULL, 5, 'Supresso Exotic Blend Coffee Beans', 'supresso-exotic-blend-coffee-beans-sup021b', 'SUP021B', 'Nuansa cokelat manis - Natural - Rasa Biji Kopi Asli', '20% Arabica - 80% Robusta. An 20/80 blend of Arabica and Robusta roasted with the City+ Roast mode and consisting of only Indonesian beans. Its lowest acidity amongst our Gourmet Collection and high bitterness characterise this blend, with sweet chocolaty aftertastes and woody, nuttiness in its undertones.', 'Can', '1 Can x 200g', 93200.00, 'images/uploads/1774419901_p_supresso-exotic-blend-coffee-beans-sup021b.webp', '[\"SUPRESSO/CANS-EXOTIC-2.webp\", \"SUPRESSO/CANS-EXOTIC-3.webp\"]', 0, '2024-11-07 09:08:02', 'https://indracostore.com/product/Supresso-Exotic-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Exotic-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/7041494429/', 'https://www.blibli.com/p/supresso-exotic-blend-coffee-beans/ps--INT-60044-00050', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:39:39');

