INSERT INTO `master_produk` VALUES (197, 8, 4, NULL, NULL, NULL, 'Supresso Single Origin Assorted Drip Coffee', 'supresso-single-origin-assorted-drip-coffee-supas10d', 'SUPAS10D', 'With coffee beans sourced from the East to the West of Indonesia, Supresso\'s collection of Indonesian single-origin coffee results in a premium range of exquisite and distinctive tastes profile. We whole-heartedly devote our premium and supreme quality coffee to all ardent coffee lovers worldwide, in beans, ground, drip, and capsule form.', 'With coffee beans sourced from the East to the West of Indonesia, Supresso\'s collection of Indonesian single-origin coffee results in a premium range of exquisite and distinctive tastes profile. We whole-heartedly devote our premium and supreme quality coffee to all ardent coffee lovers worldwide, in beans, ground, drip, and capsule form. \r\n\r\nExperience Indonesian coffee in its purest form, with Supresso.\r\n\r\nTraveling around Indonesia with us has been made easier with Single Origin Coffee Variants together in a box! Happy exploring.\r\n\r\n1x Aceh Gayo | 1x Peaberry | 1x Sumatra Madheling | 1x Lampung | 1x Manglayang | 1x West Java | 1x Java | 1x Bali Kintamani | 1x Flores Bajawa | 1x Toraja Kalosi', 'Drip', '10g x 10 Coffee Drip', 125550.00, 'SUPRESSO/251118_supresso_indraco_web_marketplace_bundle_mix_drip_1.webp', '[\"SUPRESSO/251118_supresso_indraco_web_marketplace_bundle_mix_drip2.webp\", \"SUPRESSO/251118_supresso_indraco_web_marketplace_bundle_mix_drip3.webp\"]', 0, '2025-11-24 11:19:40', NULL, 'supresso-single-origin-assorted-drip-coffee-10g-x-10-coffee-drip', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-17 15:07:41');

